//! T-19 sb-act acceptance round 5, items 24-28: D-409 (a key's class is the max over its
//! segments, so a Delete segment or DEL next to Enter still deletes on a non-text row; a
//! button or menuitem named with a pay_words phrase is Pay with or without a form), and
//! the raise-only check of hard rule 4 against the classes `crates/sb-act/src` gave at
//! 0554c29, before D-409. Public API only; fixtures are I-5 wire JSON in `common/mod.rs`.
//!
//! The baseline `bench/fixtures/t19_pre_d409_classes.txt` is regenerated by running
//! `raise_only_every_fixture_vs_pre_d409` with `T19_WRITE_BASELINE_D409=<path>` in a tree
//! whose `crates/sb-act/src` is at 0554c29 (see the round-5 section of
//! `bench/results/accept-T-19-sb-act.md`).

use std::collections::BTreeMap;

use harness_core::Class;
use sb_act::{classify_step, parse, quote, Step};
use sb_sheet::{ElemRef, IndexRow};

mod common;
use common::{raise_programs_d409, ALL, D409, KEYS, LOGIN};

const BASELINE: &str = include_str!("../../../bench/fixtures/t19_pre_d409_classes.txt");

fn rows(json: &str) -> Vec<IndexRow> {
    serde_json::from_str(json).expect("I-5 wire JSON")
}

fn class_of(program: &str, index: &[IndexRow]) -> Class {
    let steps = parse(program).unwrap_or_else(|e| panic!("{program:?}: {e}"));
    assert_eq!(steps.len(), 1, "{program:?}");
    classify_step(&steps[0], index).class
}

fn ref_of(r: &IndexRow) -> String {
    if r.frame == 0 {
        format!("#{}", r.id)
    } else {
        format!("#f{}.{}", r.frame, r.id)
    }
}

/// Class of `k<ref>=<key>` through the parser (key quoted by `q()`, D-52) and as a
/// hand-built `Step::Key`; both must agree.
fn key_class(row: &IndexRow, key: &str, index: &[IndexRow]) -> Class {
    let program = format!("k{}={}", ref_of(row), quote(key));
    let built = Step::Key {
        target: ElemRef {
            frame: row.frame,
            id: row.id,
        },
        key: key.to_string(),
    };
    let steps = parse(&program).unwrap_or_else(|e| panic!("{program:?}: {e}"));
    assert_eq!(steps, vec![built.clone()], "{program:?}");
    let parsed = classify_step(&steps[0], index).class;
    assert_eq!(parsed, classify_step(&built, index).class, "{program:?}");
    parsed
}

fn row(index: &[IndexRow], frame: u32, id: u32) -> &IndexRow {
    index
        .iter()
        .find(|r| r.id == id && r.frame == frame)
        .unwrap_or_else(|| panic!("no row #f{frame}.{id}"))
}

/// Key values with an Enter segment and a Delete segment (or DEL) under D-409 (1).
const ENTER_DELETE_CHORDS: &[&str] = &[
    "Enter+Delete",
    "Enter+Del",
    "Control+Enter+Delete",
    "Return+Shift+Delete",
    "Enter\u{7f}",
    "\u{7f}Enter",
    "Delete+Enter",
    "Del Enter",
    "Enter\tDelete",
    "\rDelete",
    "NumpadEnter+Delete",
    "Del+Return",
    "Shift+Delete+Enter",
    "enter+delete",
    "ENTER+DEL",
];

/// Key values with a Delete segment and no Enter: Delete (or higher) on a non-text row.
const DELETE_ONLY: &[&str] = &["Delete", "Del", "DEL", "Control+Delete", "Delete+a"];

/// Key values that only contain the letters of Delete or Del: not Delete (whole segments).
const NOT_DELETE: &[&str] = &[
    "Delegate",
    "Deleted",
    "Undelete",
    "Delete2",
    "Shift+Delegate",
    "Delivery",
];

// ---- item 24: D-409 (1) chord max on named rows ----

#[test]
fn d409_enter_delete_chords_on_non_text_rows() {
    let d = rows(D409);
    let keys = rows(KEYS);
    // Formless Inbox rows: a click is Navigate or Fill, Enter is that click, Delete wins.
    let cases: [(&[IndexRow], u32, Class, &str); 10] = [
        (&d, 400, Class::Delete, "formless mail row"),
        (&d, 401, Class::Delete, "formless Archive button"),
        (&d, 402, Class::Delete, "formless selection checkbox"),
        (&d, 404, Class::Delete, "nav link"),
        (&keys, 106, Class::Delete, "KEYS mail row"),
        (&keys, 107, Class::Delete, "KEYS selection checkbox"),
        // In a card form Enter is Pay, which is above Delete.
        (&d, 406, Class::Pay, "Save card checkbox in a card form"),
        (&d, 407, Class::Pay, "card form SUBMIT"),
        // In a signup form Enter is Account, below Delete.
        (&d, 409, Class::Delete, "Remember me checkbox in signup"),
        (&d, 410, Class::Delete, "signup SUBMIT"),
    ];
    for (idx, id, want, what) in cases {
        let r = row(idx, 0, id);
        for k in ENTER_DELETE_CHORDS {
            assert_eq!(key_class(r, k, idx), want, "{what} k#{id}={k:?}");
        }
    }
    // Before D-409 these were the Enter class; the round-4 review's seven shapes on the
    // mail row are now Delete.
    let mail = row(&d, 0, 400);
    for k in [
        "Enter+Delete",
        "Enter+Del",
        "Control+Enter+Delete",
        "Return+Shift+Delete",
        "Enter\u{7f}",
        "\u{7f}Enter",
        "Delete+Enter",
    ] {
        assert_eq!(key_class(mail, k, &d), Class::Delete, "k#400={k:?}");
        assert_eq!(class_of(&format!("k#400={}", quote(k)), &d), Class::Delete);
    }
    // A non-Enter chord with Delete on a card-form checkbox is Delete, not the form's Pay.
    assert_eq!(key_class(row(&d, 0, 406), "Delete+a", &d), Class::Delete);
    for k in DELETE_ONLY {
        assert_eq!(key_class(mail, k, &d), Class::Delete, "k#400={k:?}");
    }
}

#[test]
fn d409_enter_delete_chords_in_text_fields_are_enter() {
    let d = rows(D409);
    let login = rows(LOGIN);
    let cases: [(&[IndexRow], u32, Class, &str); 4] = [
        (&d, 405, Class::Pay, "card number field"),
        (&d, 408, Class::Account, "signup email field"),
        (&d, 403, Class::Submit, "formless search field"),
        (&login, 21, Class::Submit, "login password field"),
    ];
    for (idx, id, want, what) in cases {
        let r = row(idx, 0, id);
        assert_eq!(key_class(r, "Enter", idx), want, "{what} Enter");
        for k in ENTER_DELETE_CHORDS {
            assert_eq!(key_class(r, k, idx), want, "{what} k#{id}={k:?}");
        }
    }
}

// ---- item 25: D-409 (2) pay_words buttons and menuitems are Pay without a form ----

#[test]
fn d409_formless_pay_buttons_are_pay() {
    let d = rows(D409);
    for (id, what) in [
        (420, "Pay now, no heading"),
        (421, "Pay $20.00 under Order summary"),
        (422, "Complete purchase, card form in frame 2"),
        (424, "menuitem Buy now"),
        (425, "Place your order"),
        (426, "header Checkout button"),
        (427, "Subscribe for $9.99/month"),
        (428, "menuitem Payment methods (one extra ask, D-409 (2))"),
        (429, "Donate"),
    ] {
        let r = row(&d, 0, id);
        assert!(r.form.is_none(), "#{id} must be formless");
        assert!(
            !r.flags.submit && !r.state.submitish,
            "#{id} must be non-submit"
        );
        assert_eq!(
            class_of(&format!("c#{id}"), &d),
            Class::Pay,
            "c#{id} {what}"
        );
        for k in ["Space", "Enter", "Return+Shift"] {
            assert_eq!(key_class(r, k, &d), Class::Pay, "k#{id}={k} {what}");
        }
    }
    // #422: no frame-0 form shares its "Checkout" heading; the card form is in frame 2.
    assert!(d
        .iter()
        .filter(|r| r.frame == 0 && r.heading.as_deref() == Some("Checkout"))
        .all(|r| r.form.is_none()));
    assert_eq!(row(&d, 2, 423).form.as_deref(), Some("f1"));
    // The frame-2 card field itself: Enter in a card form is Pay, typing is Fill.
    assert_eq!(class_of("k#f2.423=Enter", &d), Class::Pay);
    assert_eq!(class_of("t#f2.423=4242", &d), Class::Fill);
}

// ---- item 26: negatives ----

#[test]
fn d409_negatives() {
    let d = rows(D409);
    // Buttons that are not pay_words phrases stay Navigate on c#, Space and Enter.
    for (id, what) in [
        (430, "Back to top"),
        (431, "Show details under Order summary"),
        (432, "formless Confirm under Checkout"),
        (436, "formless Complete under Checkout"),
        (440, "Repay later"),
        (441, "Payroll settings"),
        (442, "Order history"),
        (443, "Display options"),
        (444, "bare Subscribe"),
        (445, "formless Book now"),
        (446, "a button named Delegate"),
        (447, "Top"),
    ] {
        let r = row(&d, 0, id);
        assert_eq!(
            class_of(&format!("c#{id}"), &d),
            Class::Navigate,
            "c#{id} {what}"
        );
        for k in ["Space", "Enter"] {
            assert_eq!(key_class(r, k, &d), Class::Navigate, "k#{id}={k} {what}");
        }
    }
    // Links are never raised by D-409 (2), whatever their name.
    for (id, what) in [
        (433, "link Pay"),
        (434, "link Pay now"),
        (435, "link Checkout"),
    ] {
        let r = row(&d, 0, id);
        assert_eq!(
            class_of(&format!("c#{id}"), &d),
            Class::Navigate,
            "c#{id} {what}"
        );
        assert_eq!(
            key_class(r, "Enter", &d),
            Class::Navigate,
            "k#{id}=Enter {what}"
        );
    }
    // Pay-named checkables only toggle: Fill, not Pay.
    for (id, what) in [
        (437, "radio Pay with PayPal"),
        (438, "checkbox Pay later"),
        (439, "tab Payment"),
    ] {
        assert_eq!(
            class_of(&format!("c#{id}"), &d),
            Class::Fill,
            "c#{id} {what}"
        );
    }
    // Look-alike key names are not Delete: the row's click class.
    let mail = row(&d, 0, 400);
    for k in NOT_DELETE {
        assert_eq!(key_class(mail, k, &d), Class::Navigate, "k#400={k:?}");
    }
    assert_eq!(class_of("k#400=Delegate", &d), Class::Navigate);
    assert_eq!(key_class(mail, "Backspace+Enter", &d), Class::Navigate);
    assert_eq!(key_class(row(&d, 0, 402), "Delegate", &d), Class::Fill);
    // Text fields keep Shift+Delete (and Delete, Del) as Fill, in or out of a form.
    let login = rows(LOGIN);
    for (idx, id, what) in [
        (&d, 403, "formless search field"),
        (&d, 405, "card number field"),
        (&d, 408, "signup email field"),
        (&login, 21, "login password field"),
    ] {
        let r = row(idx, 0, id);
        for k in ["Shift+Delete", "Delete", "Del", "Shift+Del"] {
            assert_eq!(key_class(r, k, idx), Class::Fill, "{what} k#{id}={k:?}");
        }
    }
    assert_eq!(class_of("k#405=Shift+Delete", &d), Class::Fill);
}

// ---- item 27: D-409 properties over every fixture ----

#[test]
fn d409_chord_is_max_of_its_segments_every_fixture() {
    let mut checked = 0;
    for (name, json) in ALL {
        let idx = rows(json);
        for r in &idx {
            let rf = ref_of(r);
            let enter = key_class(r, "Enter", &idx);
            let delete = key_class(r, "Delete", &idx);
            let click = class_of(&format!("c{rf}"), &idx);
            if r.flags.challenge {
                assert_eq!(enter, Class::Challenge, "{name} {rf}");
            }
            for k in ENTER_DELETE_CHORDS {
                let want = enter.max(delete);
                assert_eq!(key_class(r, k, &idx), want, "{name} k{rf}={k:?}");
                checked += 1;
            }
            // Del is Delete's alias on every row.
            assert_eq!(key_class(r, "Del", &idx), delete, "{name} k{rf}=Del");
            // A Delete key that only edits text (Fill) marks a text field: Shift+Delete is
            // Fill there and every Enter+Delete chord is exactly the Enter class.
            if delete == Class::Fill {
                assert_eq!(
                    key_class(r, "Shift+Delete", &idx),
                    Class::Fill,
                    "{name} {rf}"
                );
                for k in ENTER_DELETE_CHORDS {
                    assert_eq!(key_class(r, k, &idx), enter, "{name} text k{rf}={k:?}");
                }
            } else {
                assert!(delete >= Class::Delete, "{name} k{rf}=Delete: {delete:?}");
            }
            for k in NOT_DELETE {
                assert_eq!(key_class(r, k, &idx), click, "{name} k{rf}={k:?}");
                checked += 1;
            }
        }
    }
    assert!(checked > 4000, "only {checked} checks");
}

#[test]
fn d409_pay_name_raises_buttons_not_links_every_fixture() {
    let mut checked = 0;
    for (name, json) in ALL {
        let base = rows(json);
        for (i, r) in base.iter().enumerate() {
            let rf = ref_of(r);
            let mut idx = base.clone();
            idx[i].name = "Pay now".to_string();
            let got = class_of(&format!("c{rf}"), &idx);
            if r.flags.challenge {
                assert_eq!(got, Class::Challenge, "{name} {rf}");
                continue;
            }
            match r.role.as_str() {
                "button" | "menuitem" => {
                    assert_eq!(got, Class::Pay, "{name} {rf} {} as Pay now", r.role);
                    checked += 1;
                }
                "link" => {
                    assert_eq!(got, Class::Navigate, "{name} {rf} link as Pay now");
                    checked += 1;
                }
                "checkbox" | "radio" | "switch" | "option" | "tab" => {
                    assert_eq!(got, Class::Fill, "{name} {rf} {} as Pay now", r.role);
                    checked += 1;
                }
                _ => {}
            }
        }
    }
    assert!(checked > 100, "only {checked} checks");
}

// ---- item 28: raise-only (hard rule 4) against the 0554c29 (pre-D-409) baseline ----

fn class_by_name(s: &str) -> Class {
    *Class::ALL
        .iter()
        .find(|c| format!("{c:?}") == s)
        .unwrap_or_else(|| panic!("unknown class {s:?}"))
}

/// Every (fixture, row, probe) of `common::ALL` x `common::raise_programs_d409`.
fn current_classes() -> BTreeMap<(String, String, String), Class> {
    let mut out = BTreeMap::new();
    for (name, json) in ALL {
        let idx = rows(json);
        for r in &idx {
            for (label, program) in raise_programs_d409(r) {
                let key = (name.to_string(), ref_of(r), label);
                let class = class_of(&program, &idx);
                assert!(out.insert(key.clone(), class).is_none(), "dup {key:?}");
            }
        }
    }
    out
}

#[test]
fn raise_only_every_fixture_vs_pre_d409() {
    let now = current_classes();
    if let Ok(path) = std::env::var("T19_WRITE_BASELINE_D409") {
        let mut text = String::from(
            "# T-19 item 28: class per (fixture, row, probe) with crates/sb-act/src at 0554c29\n",
        );
        for ((f, r, l), c) in &now {
            text.push_str(&format!("{f}\t{r}\t{l}\t{c:?}\n"));
        }
        std::fs::write(&path, text).expect("write baseline");
        eprintln!("wrote {} entries to {path}", now.len());
        return;
    }
    let mut base = BTreeMap::new();
    for line in BASELINE
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
    {
        let p: Vec<&str> = line.split('\t').collect();
        assert_eq!(p.len(), 4, "bad baseline line {line:?}");
        base.insert(
            (p[0].to_string(), p[1].to_string(), p[2].to_string()),
            class_by_name(p[3]),
        );
    }
    assert_eq!(
        base.keys().collect::<Vec<_>>(),
        now.keys().collect::<Vec<_>>(),
        "baseline and probes differ; regenerate the baseline"
    );
    let mut raised = 0;
    let mut lowered = Vec::new();
    for (k, &b) in &base {
        let c = now[k];
        if c < b {
            lowered.push(format!("{k:?}: {b:?} -> {c:?}"));
        } else if c > b {
            raised += 1;
            eprintln!("raised {k:?}: {b:?} -> {c:?}");
        }
    }
    eprintln!(
        "{} probes, {raised} raised, {} lowered",
        base.len(),
        lowered.len()
    );
    assert!(base.len() > 6000, "only {} probes", base.len());
    assert!(lowered.is_empty(), "lowered:\n{}", lowered.join("\n"));
}
